import math
from functools import reduce

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a*b) // gcd(a, b)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(gcd, numbers)

def list_lcm(numbers):
    if not numbers:
        return 1 # LCM of an empty set is conventionally 1, but here sets are non-empty
    return reduce(lcm, numbers)

def calculate_good_partitions(sequence):
    n = len(sequence)
    good_partitions = 0
    # Check partitions for k = 1 to n-1
    for k in range(1, n):
        A_k = sequence[:k]
        B_k = sequence[k:]

        lcm_Ak = list_lcm(A_k)
        gcd_Bk = list_gcd(B_k)

        if lcm_Ak == gcd_Bk:
            good_partitions += 1
    return good_partitions

# Test cases based on the simplest sequence (1, 2, ..., n)
n_tests = [2, 3, 4, 5]
results = {}

for n in n_tests:
    sequence = list(range(1, n + 1))
    N_good = calculate_good_partitions(sequence)
    results[n] = N_good

print(results)

import math
from functools import reduce

def lcm(a, b):
    return abs(a*b) // math.gcd(a, b)

def list_lcm(numbers):
    if not numbers:
        return 1
    return reduce(lcm, numbers)

def list_gcd(numbers):
    if not numbers:
        return 0
    return reduce(math.gcd, numbers)

def calculate_N_good(n):
    if n < 2:
        return 0

    count = 0
    # k runs from 1 to n-1
    for k in range(1, n):
        # A_k = {1, 2, ..., k}
        L_k = list_lcm(list(range(1, k + 1)))

        # B_k = {k+1, k+2, ..., n}
        B_k = list(range(k + 1, n + 1))
        G_k = list_gcd(B_k)

        if L_k == G_k:
            count += 1
    return count

# Test small values of n
print(f"N_good(2) = {calculate_N_good(2)}")
print(f"N_good(3) = {calculate_N_good(3)}")
print(f"N_good(4) = {calculate_N_good(4)}")
print(f"N_good(5) = {calculate_N_good(5)}")
print(f"N_good(10) = {calculate_N_good(10)}")

